import {JOURNAL_KEY,recoverDrafts} from './drafts.mjs';
import {course} from '../content/course.mjs';
import {PERSONS} from '../content/verbs.mjs';
import {dayKey,emptyStore,newProfile,eligibleCards,plan,startDiagnostic,commit,undo,grade,evidenceState,diagnosticReport,normalize,vocabularyScope,practiceQueue,pendingSessions,showActiveSession} from './engine.mjs';
import {openRepository,memoryRepository,previewBackup,exportBackup,compactState,MAX_BACKUP_BYTES,exportProfileBackup,addImportedProfile} from './persistence.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const main=$('#main'),modal=$('#modal');
const nav=[['today','◈','Today'],['course','▤','Course'],['words','▧','Words'],['verbs','⌁','Verbs'],['practice','✳','Practice'],['progress','▥','Progress'],['settings','⚙','Settings']];
let data,state,repo,volatile=false,stale=false,saving=Promise.resolve(),page='today',chapter=null,query='',wordPage=0,wordBox='all',verbQuery='',practiceChapter='2b',practiceKind='all',toastTimer,lastFocus,importPreview=null;
let pendingDrafts=new Map(),draftTimer,guestContext=null,assignmentScope=null;
const p=()=>state.profiles.find(x=>x.id===state.activeProfile);
const s=()=>p().sessions.find(x=>x.id===p().activeSession);
const ex=id=>course.exercises.find(e=>e.id===id),obj=id=>course.objectives.find(o=>o.id===id);
const chapterName=id=>course.chapters.find(c=>c.id===id)?.title||id;
const label=id=>id.startsWith('pe-')?'INTRO':id.toUpperCase();
const kindName=kind=>({sentence:'Build a complete sentence','scene-choice':'Use a scene',guided:'Sentence practice',typed:'Recall in context',form:'Verb form',cloze:'Complete a sentence','select-conjugate':'Choose and conjugate',all:'Mixed practice',grammar:'Grammar in context',reading:'Reading',listening:'Listening',writing:'Writing',speaking:'Speaking'})[kind]||kind;
const tag=(text,yellow=false)=>`<span class="tag ${yellow?'yellow-tag':''}">${esc(text)}</span>`;
const button=(text,action,cls='',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const refs=urls=>urls.map(u=>`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(new URL(u).hostname)} ↗</a>`).join(' · ');
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6500);}
function status(message,error=false){const el=$('#save-state');if(el.textContent!==message)el.textContent=message;el.classList.toggle('error',error);$('#save-actions').hidden=!error;}
const channel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('palabra-state-v2'):null;
channel?.addEventListener('message',e=>{if(!guestContext&&e.data>state?.revision){stale=true;status('Newer progress in another tab. Reload to continue.',true);toast('Another tab saved progress. Reload before your next answer.');}});
function mutate(fn,{renderAfter=true}={}){
 const job=saving.then(async()=>{
  if(stale)throw Error('Another tab saved progress. Reload this tab before continuing.');
  const entries=[...pendingDrafts.values()];const next=compactState(state);
  for(const entry of entries){const se=next.profiles.find(x=>x.id===entry.profileId)?.sessions.find(x=>x.id===entry.sessionId);if(se&&!se.completedAt&&!se.feedback&&se.cursor===entry.index)se.drafts[entry.index]={...se.drafts[entry.index],answer:entry.answer};}
  await fn(next,next.profiles.find(x=>x.id===next.activeProfile));
  try{state=await repo.write(next,state.revision);}catch(error){if(/Another tab/.test(error.message)){stale=true;throw error;}volatile=true;repo=memoryRepository(state);state=await repo.write(next,state.revision);toast('Device storage could not save. Practice continues in memory. Export a backup before closing this tab.');}
  for(const entry of entries)if(pendingDrafts.get(entry.sessionId)===entry)pendingDrafts.delete(entry.sessionId);
  persistDraftJournal();
  if(!volatile&&!guestContext)channel?.postMessage(state.revision);
  status(guestContext?'Temporary guest · download before ending':volatile?'Practice in memory only · Export before leaving':'Saved in this browser',volatile||!!guestContext);
  if(renderAfter)render();return true;
 });
 saving=job.catch(error=>{status(error.message,true);toast(error.message);});return job;
}
function showModal(title,body){lastFocus=document.activeElement;modal.innerHTML=`<div class="modal-top"><h2 id="modal-title">${esc(title)}</h2>${button('×','close-modal','','aria-label="Close dialog"')}</div>${body}`;modal.showModal();}
modal.addEventListener('close',()=>{(lastFocus?.isConnected?lastFocus:main).focus();});
function navigate(){if(location.hash.startsWith('#assignment?')){try{assignmentScope=parseAssignment(location.hash,course);page='assignment';render();main.focus();return;}catch(error){page='assignment';assignmentScope=null;main.innerHTML=`<section class="panel"><h1>Check this practice link.</h1><p>${esc(error.message)}</p><a href="#today">Back to Today</a></section>`;return;}}const parts=location.hash.slice(1).split('/');page=nav.some(n=>n[0]===parts[0])?parts[0]:'today';chapter=parts[1]||null;render();main.focus();window.scrollTo(0,0);}
const intro=(title,subtitle,eyebrow='POCO A POCO · LITTLE BY LITTLE',at=Date.now())=>`<section class="intro"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><span class="date">${new Date(at).toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'})}</span></section>`;
function render(){
 if(!state)return;$('#nav').innerHTML=nav.map(([id,icon,text],i)=>`<a class="${i>=3?'nav-later':''}" href="#${id}" ${page===id?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${text}</a>`).join('')+button(['today','course','words'].includes(page)?'More ▾':`More · ${nav.find(n=>n[0]===page)?.[2]||'Practice link'} ▾`,'more-nav','mobile-more','aria-expanded="false" aria-controls="mobile-nav"')+`<div id="mobile-nav" hidden>${nav.slice(3).map(([id,,text])=>`<a href="#${id}" ${page===id?'aria-current="page"':''}>${text}</a>`).join('')}</div>`;$('#page-label').textContent=page==='assignment'?'Practice link':nav.find(n=>n[0]===page)?.[2];$('#profile-name').textContent=p().displayName;$('#guest-control').textContent=guestContext?'End guest session':'Guest mode';$('#guest-control').dataset.action=guestContext?'guest-end':'guest-start';
 if(page==='assignment'){renderAssignment();return;}
 if(!p().onboarded){renderOnboarding();return;}
 if(page==='today'&&showActiveSession(s(),Date.now())){renderSession();return;}
 ({today:renderToday,course:renderCourse,words:renderWords,verbs:renderVerbs,practice:renderPractice,progress:renderProgress,settings:renderSettings}[page]||renderToday)();
 for(const b of main.querySelectorAll('[data-kind=writing],[data-kind=speaking]')){if(p().attempts.some(a=>a.exerciseId===b.dataset.kind+'-'+b.dataset.chapter&&a.outcome==='self-assessed')){const note=document.createElement('small');note.className='tiny';note.textContent=' ✓ Response completed · self-assessed';b.after(note);}}
}
const positionOptions=selected=>course.chapters.map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${label(c.id)} · ${esc(c.title)}</option>`).join('');
function renderOnboarding(){main.innerHTML=`<section class="onboarding"><div class="eyebrow">WELCOME TO YOUR STUDY SPACE</div><h1>A little Spanish.<br>Every day.</h1><p>A clear daily path, real sentences, and room to make mistakes. Start with the catch-up path through 2B, or choose where your class is now.</p><form id="onboarding-form" class="panel"><div class="field"><label for="display-name">Local display name (optional)</label><input id="display-name" maxlength="60" value="${esc(p().displayName==='Learner'?'':p().displayName)}" placeholder="What should we call you?"></div><div class="toolbar"><div class="field"><label for="class-position">Class position</label><select id="class-position">${positionOptions(p().settings.position)}</select></div><div class="field"><label for="time-budget">Daily time</label><select id="time-budget">${[10,15,20].map(n=>`<option ${n===15?'selected':''} value="${n}">${n} minutes</option>`).join('')}</select></div></div><p class="tiny">Local profiles stay in this browser and are readable by others using it. Use a temporary guest session on a shared device. No account is needed.</p><div class="actions"><button class="primary" type="submit" name="path" value="diagnostic">Take the short diagnostic →</button><button type="submit" name="path" value="skip">Start from the beginning</button></div><p class="tiny">20 questions, through 2B. You can say “I don’t know.” Results are provisional, never a mastery score.</p></form>${button('Practice as a temporary guest','guest-start')} ${button('Restore a Palabra backup','import-dialog','text-button')}<p class="tiny">Independent vocabulary lists and original lessons aligned to Spanish 1 topics. Exact textbook edition and teacher pacing remain unverified.</p></section>`;}
function metrics(){const selected=eligibleCards(data.cards,p().settings),progress=p().progress;return {selected,due:selected.filter(c=>progress[c.id]?.due<=Date.now()).length,fresh:selected.filter(c=>!progress[c.id]).length,seen:selected.filter(c=>progress[c.id]).length,late:selected.filter(c=>progress[c.id]?.box>=4).length};}
function renderToday(){
 const m=metrics(),pending=pendingSessions(p()),scoped=course.objectives.filter(o=>course.chapters.findIndex(c=>c.id===o.chapterId)<=course.chapters.findIndex(c=>c.id===p().settings.position));
 const secure=scoped.filter(o=>evidenceState(p().attempts,o,Date.now()).state==='secure').length,attempts=p().attempts.filter(a=>dayKey(a.timestamp)===dayKey(Date.now()));
 const preview=pending[0]||plan(p(),course,data.cards,Date.now(),1),remaining=preview.queue.slice(preview.cursor),wordCount=remaining.filter(i=>i.kind==='vocabulary').length,pattern=remaining.find(i=>i.kind==='exercise'&&ex(i.exerciseId)?.objectiveIds.some(id=>!obj(id)?.receptive)),patternTitle=pattern?obj(ex(pattern.exerciseId).objectiveIds[0])?.title:'Spanish in context',planText=[wordCount?`${wordCount} word activities`:'',pattern?patternTitle:'',...[['reading','short reading'],['listening','listening'],['writing','writing'],['speaking','speaking']].filter(([kind])=>remaining.some(i=>i.exerciseId&&ex(i.exerciseId)?.kind===kind)).map(([,label])=>label)].filter(Boolean).join(' · ');
 main.innerHTML=`${intro(`A little today, ${p().displayName==='Learner'?'a little stronger':p().displayName}.`,'A short plan, at your pace.')}<section class="hero"><div><div class="eyebrow">YOUR DAILY LEARNING PLAN</div><h2>${pending.length?'Pick up where you left off.':'Make room for Spanish.'}</h2><p>${esc(planText)}. About ${esc(preview.settings.minutes)} minutes.</p>${button(pending.length?'Resume daily practice →':'Start daily practice →',pending.length?'resume-latest':'start-daily','yellow')}</div><div class="hero-art" aria-hidden="true"><div class="paper-card"></div><div class="paper-card"></div><div class="paper-card">poco a poco<small>LITTLE BY LITTLE</small></div></div></section><section class="metrics" aria-label="Your learning at a glance"><div class="metric"><label>Ready for review</label><b>${m.due}</b><span>Previously studied words</span></div><div class="metric"><label>Words introduced</label><b>${m.seen}</b><span>Of ${m.selected.length} selected cards</span></div><div class="metric"><label>Secure skills</label><b>${secure}<span> / ${scoped.length}</span></b><span>Evidence across days</span></div><div class="metric"><label>Practice today</label><b>${attempts.length}</b><span>Saved activities</span></div></section><div class="grid"><section class="panel"><div class="stack"><h3>A balanced little routine</h3>${tag(`${esc(p().settings.minutes)} MIN`,true)}</div><ol class="steps"><li><span class="step-number">1</span><div>Remember & reconnect<small>Due words first; at most ${esc(p().settings.newLimit)} new words a day</small></div></li><li><span class="step-number">2</span><div>Learn a pattern, use a sentence<small>Prerequisites and diagnostic gaps guide the plan</small></div></li><li><span class="step-number">3</span><div>Read, listen, make it yours<small>Short comprehension and a personal response</small></div></li></ol></section><section class="panel highlight"><div class="eyebrow">YOUR COURSE POSITION</div><h2 style="margin-top:14px">${label(p().settings.position)} · ${esc(chapterName(p().settings.position))}</h2><p>Your class position limits new daily material. Earlier skills return when they need care.</p><a class="text-button" href="#course/${p().settings.position}">Explore your course →</a><div class="bar"><span style="width:${secure/scoped.length*100}%"></span></div><p class="tiny">${secure} secure objectives. A word box alone does not establish language mastery.</p></section></div>${pending.length?`<section class="panel"><h3>Unfinished sessions</h3>${pending.map(x=>`<p>${button(`${x.diagnostic?'Diagnostic':x.practiceOnly?'Extra vocabulary':'Learning session'} · ${x.cursor}/${x.queue.length} · ${new Date(x.createdAt).toLocaleDateString()}`,'resume','','data-id="'+esc(x.id)+'"')}</p>`).join('')}</section>`:''}<section class="panel"><div class="stack"><h3>Find your starting point</h3>${tag('PROVISIONAL PLACEMENT')}</div><p>Sample the catch-up skills through 2B. Your vocabulary boxes stay exactly as they are.</p>${button('Take / retake diagnostic','diagnostic')}</section><p class="tiny">${guestContext?'Temporary guest work stays only in this tab. Download a backup before ending.':volatile?'⚠ Practice is only in memory. Export before closing.':'Progress saves in this browser. Export a backup to move it to another device.'}</p>`;
}
function lessonHtml(o){const l=course.lessons.find(l=>l.objectiveIds.includes(o.id));return `<div class="eyebrow">${esc(o.skillType)} · ${label(o.chapterId)}</div><h2>${esc(o.title)}</h2><p>${esc(l.explanation)}</p><div class="lesson-examples" lang="es">${l.examples.map(e=>`<p>${esc(e)}</p>`).join('')}</div><div class="callout"><b>A common mix-up</b><p>${esc(l.commonMistakes[0])}</p></div><p class="tiny">${refs(l.sourceRefs)}</p>`;}
function renderCourse(){
 const c=course.chapters.find(c=>c.id===chapter);if(!c){main.innerHTML=`${intro('A path, one step at a time.','Explore the whole course, from first greetings through 9B.','YOUR COURSE')}<div class="panel">${course.chapters.map(c=>{const os=course.objectives.filter(o=>o.chapterId===c.id),n=os.filter(o=>evidenceState(p().attempts,o,Date.now()).state==='secure').length;return `<article class="course-card"><div class="chapter-badge">${label(c.id)}</div><div><h3>${esc(c.title)}</h3><p>${esc(c.subtitle)} · ${os.length} objectives · ${n} secure</p>${tag(n===os.length&&os.every(o=>p().lessons.includes(o.id))?'Secure graded objectives':'Available lessons & practice')}</div>${button('Explore →','chapter','','data-id="'+c.id+'"')}</article>`;}).join('')}</div><p class="tiny">The introduction has three teaching topics. The vocabulary’s four introductory source lists remain separate filters. Every chapter contains original lessons and exercises; exact edition alignment is unverified.</p>`;return;}
 const os=course.objectives.filter(o=>o.chapterId===c.id),culture=course.cultures.find(n=>n.chapterId===c.id);
 main.innerHTML=`${intro(c.title,c.subtitle,`${label(c.id)} · YOUR COURSE`)}<a href="#course">← All chapters</a><div class="grid" style="margin-top:25px"><section class="panel"><h2>Learn the patterns.</h2>${os.map(o=>{const st=evidenceState(p().attempts,o,Date.now());return `<article class="objective"><div class="stack"><h3>${esc(o.title)}</h3>${tag(st.state)}</div><p>${p().lessons.includes(o.id)?'Lesson explored':'New lesson'} · ${st.n} independent attempts · ${course.exercises.filter(e=>e.objectiveIds.includes(o.id)&&!e.vosotros).length} authored variants</p><p class="tiny">${o.prerequisites.length?'Builds on: '+o.prerequisites.map(id=>esc(obj(id).title)).join(', '):'A starting-point skill'}</p><div class="stack">${button('Read lesson','lesson','','data-id="'+o.id+'"')}${button('Practice this skill','skill','','data-id="'+o.id+'"')}</div></article>`;}).join('')}</section><div><section class="panel highlight"><h2>Use it in the world.</h2><p>Understand a short message, then make one of your own.</p>${['sentence',...(course.exercises.some(e=>e.chapterId===c.id&&e.kind==='scene-choice')?['scene-choice']:[]), 'reading','listening','writing','speaking'].map(kind=>`<p>${button(({sentence:'Build a whole sentence','scene-choice':'Use a scene',reading:'Read a short passage',listening:'Listen & understand',writing:'Write a few sentences',speaking:'Say it aloud'})[kind],'chapter-practice','','data-chapter="'+c.id+'" data-kind="'+kind+'"')}</p>`).join('')}<a href="#words">Connect with the word library →</a></section><section class="panel"><div class="eyebrow">A CULTURAL WINDOW · ${esc(culture.community)}</div><h3 style="margin-top:15px">Notice, compare, ask.</h3><p>${esc(culture.text)}</p><p><b>${esc(culture.prompt)}</b></p><p class="tiny">${refs(culture.sourceRefs)}</p></section></div></div>`;
}
function boxHtml(){const selected=eligibleCards(data.cards,p().settings);return `<div class="boxes" aria-label="Five Leitner boxes">${[1,2,3,4,5].map((b,i)=>`<button class="box" data-action="box-filter" data-id="${b}"><small>BOX ${b}</small><b>${selected.filter(c=>(p().progress[c.id]?.box||1)===b).length}</b><small>${[1,2,4,7,14][i]}-day interval</small></button>`).join('')}</div>`;}
function renderWords(){
 let selected=eligibleCards(data.cards,p().settings),list=selected.filter(c=>(!query||normalize(c.spanish+' '+c.english).normalize('NFD').replace(/\p{M}/gu,'').includes(normalize(query).normalize('NFD').replace(/\p{M}/gu,'')))&&(wordBox==='all'||wordBox==='new'&&!p().progress[c.id]||String(p().progress[c.id]?.box||1)===wordBox));const pages=Math.max(1,Math.ceil(list.length/25));wordPage=Math.min(wordPage,pages-1);
 main.innerHTML=`${intro('Meet your palabras.','Hear a word, recall its meaning, give it room to stick.','YOUR WORD LIBRARY')}<div class="stack">${button('Choose vocabulary chapters','word-filters')}${button('Scheduled word review','start-words','primary')}${button('Practice anytime','practice-words')}</div>${boxHtml()}<p class="tiny">${p().history.filter(h=>dayKey(h.at)===dayKey(Date.now())).length} scheduled vocabulary reviews today. Unseen cards are included in Box 1. Both translation directions share one schedule; recognition does not prove production. Practice anytime leaves schedules and evidence unchanged.</p><div class="toolbar"><div class="field"><label for="word-search">Spanish or English</label><input id="word-search" placeholder="Find a word or phrase…" value="${esc(query)}"></div><div class="field"><label for="word-box">Card filter</label><select id="word-box"><option value="all">All boxes</option><option value="new">Unseen only</option>${[1,2,3,4,5].map(b=>`<option value="${b}" ${wordBox===String(b)?'selected':''}>Box ${b}</option>`).join('')}</select></div><label class="check"><input id="word-verbs" type="checkbox" ${p().settings.verbsOnly?'checked':''}>Verb phrases</label></div><div class="word-list">${list.slice(wordPage*25,wordPage*25+25).map(c=>`<article class="word-row"><div><strong lang="es">${esc(c.spanish)}</strong><small>${c.sections.map(id=>esc(id.toUpperCase())).join(' · ')} · ${p().progress[c.id]?`Box ${p().progress[c.id].box} · due ${new Date(p().progress[c.id].due).toLocaleDateString()}`:'Unseen'}</small></div><p>${esc(c.english)}</p>${button('◖))','speak-word','speaker','data-id="'+c.id+'" aria-label="Hear '+esc(c.spanish)+'"')}</article>`).join('')||'<div class="empty"><h3>No words found.</h3><p>Try another search or vocabulary chapter filter.</p></div>'}</div><div class="section-heading"><p class="tiny">${list.length?wordPage*25+1:0}–${Math.min(list.length,(wordPage+1)*25)} of ${list.length} · ${selected.length} selected cards</p><div class="stack">${button('←','word-prev','','aria-label="Previous words" '+(wordPage===0?'disabled':''))}${button('→','word-next','','aria-label="Next words" '+(wordPage>=pages-1?'disabled':''))}</div></div><p class="tiny">${esc(data.sourceNote)} Stable IDs preserve existing backups. Independent dataset; exact textbook edition transcription has not been established.</p>`;$('#word-box').value=wordBox;
}
function renderVerbs(){const list=course.verbs.filter(v=>normalize(v.infinitive+' '+v.meaning).includes(normalize(verbQuery)));main.innerHTML=`${intro('Patterns you can use.','A reference to learn from. Active practice to make it yours.','VERB WORKSHOP')}<div class="field"><label for="verb-search">Search infinitive or English meaning</label><input id="verb-search" value="${esc(verbQuery)}" placeholder="estar, to know, to ask…"></div><p class="tiny">${p().settings.vosotros?'Vosotros is visible and enabled for drills.':'Ustedes is the default plural address. Turn on vosotros in Settings for its drills.'} Looking up a form is exposure, not successful recall.</p>${list.map(v=>`<details class="panel"><summary><b lang="es">${esc(v.infinitive)}</b> · ${esc(v.meaning)} ${tag(label(v.firstChapter))}</summary><p>${esc(v.notes)}</p><p class="lesson-examples" lang="es">${esc(v.example)}</p>${Object.entries(v.forms).map(([tense,forms])=>`<h3>${esc(tense==='affirmative-tú'?'Affirmative tú command':tense)}</h3><div class="table-wrap"><table><thead><tr><th>Subject</th><th>Form · ending underlined when regular</th></tr></thead><tbody>${forms.map((form,i)=>!p().settings.vosotros&&i===4&&tense!=='affirmative-tú'?'':`<tr><td>${esc(tense==='affirmative-tú'?'tú (affirmative)':PERSONS[i])}</td><td class="verb-form" lang="es">${v.notes.startsWith('Regular')&&tense==='present'?esc(form.slice(0,v.infinitive.length-2))+'<u>'+esc(form.slice(v.infinitive.length-2))+'</u>':esc(form)}</td></tr>`).join('')}</tbody></table></div>`).join('')}<p class="tiny">${refs(v.sourceRefs)}</p><div class="actions">${button('Practice in context','verb-practice','','data-id="'+v.id+'"')}${button('Hear infinitive','speak-verb','','data-id="'+v.id+'"')}</div></details>`).join('')||'<p>No matching validated verb.</p>'}`;}
function renderPractice(){const list=course.exercises.filter(e=>e.chapterId===practiceChapter&&(practiceKind==='all'||e.kind===practiceKind||practiceKind==='grammar'&&!['reading','listening','writing','speaking'].includes(e.kind))&&(!e.vosotros||p().settings.vosotros));main.innerHTML=`${intro('Make it your own.','Choose a skill, hear a message, or try a real sentence.','YOUR PRACTICE STUDIO')}<div class="toolbar"><div class="field"><label for="practice-chapter">Chapter</label><select id="practice-chapter">${positionOptions(practiceChapter)}</select></div><div class="field"><label for="practice-kind">Practice type</label><select id="practice-kind">${['all','grammar','sentence','scene-choice','reading','listening','writing','speaking'].map(k=>`<option value="${k}" ${k===practiceKind?'selected':''}>${esc(kindName(k))}</option>`).join('')}</select></div>${button('Start selected practice →','start-selected','primary')}</div><div class="grid">${['grammar','reading','listening','writing','speaking'].map(k=>`<section class="panel"><h2>${({grammar:'Build a sentence',reading:'Read a little',listening:'Listen closely',writing:'Put it in words',speaking:'Say it aloud'})[k]}</h2><p>${({grammar:'Recall a form, fix agreement, and use a pattern in context.',reading:'Original short texts with three questions and a glossary.',listening:'Replay and slow down browser Spanish audio. Transcripts are available.',writing:'Personal prompts with checklists and models after your attempt.',speaking:'Speak aloud, hear a model, and compare against a clear rubric.'})[k]}</p>${button('Practice →','chapter-practice','','data-kind="'+k+'" data-chapter="'+practiceChapter+'"')}</section>`).join('')}</div><p class="tiny">${list.length} activities match the selected chapter/type. You may explore beyond your class position. Your daily plan follows its prerequisites.</p>${teacherPanel()}`;}

function teacherPanel(){return `<section class="panel"><h2>Share a class practice link</h2><p>A link previews a chapter, skill and time budget. Learners choose when to start. It contains no names or progress.</p><form id="teacher-link-form"><div class="toolbar"><div class="field"><label for="teacher-chapter">Class chapter</label><select id="teacher-chapter">${positionOptions(practiceChapter)}</select></div><div class="field"><label for="teacher-skill">Focus skill</label><select id="teacher-skill"><option value="">Mixed chapter practice</option>${course.objectives.filter(o=>o.chapterId===practiceChapter).map(o=>`<option value="${o.id}">${esc(o.title)}</option>`).join('')}</select></div><div class="field"><label for="teacher-minutes">Practice time</label><select id="teacher-minutes">${[10,15,20].map(n=>`<option value="${n}">${n} minutes</option>`).join('')}</select></div></div><button type="submit">Create practice link</button></form></section>`;}
function renderAssignment(){if(!assignmentScope){main.innerHTML='<p>This practice link could not open. <a href="#today">Go to Today</a>.</p>';return;}const scope=assignmentScope,preview=assignmentQueue(p(),course,scope,Date.now());main.innerHTML=`${intro('A practice link for your class.','Review the focus before you begin.','CLASS PRACTICE')}<section class="panel"><h2>${label(scope.chapter)} · ${esc(chapterName(scope.chapter))}</h2><p><b>${esc(scope.skill?obj(scope.skill).title:kindName(scope.kind))}</b> · ${scope.minutes}-minute target</p><p>${preview.ids.length} activities, including ${preview.prerequisiteCount} earlier-pattern quick checks. If you need them, brief lessons are available before each check. Your usual class position and preferences stay as they are.</p><p>Using ${guestContext?'temporary Guest':esc(p().displayName)+' in this browser'}. Local profiles are not private accounts.</p><div class="actions">${button('Start this practice →','assignment-start','primary')}${guestContext?'':button('Use a temporary guest','guest-start')}</div><a href="#today">Back to Today</a></section>`;}

function renderProgress(){const m=metrics(),all=p().attempts,scoped=course.objectives.filter(o=>course.chapters.findIndex(c=>c.id===o.chapterId)<=course.chapters.findIndex(c=>c.id===p().settings.position)),report=diagnosticReport(all,course.objectives),diag=all.filter(a=>a.diagnostic);const comp=kind=>all.filter(a=>ex(a.exerciseId)?.kind===kind&&!a.audioFallback&&!a.usedHint&&!a.revealed&&!a.retry&&!a.practiceOnly&&!a.diagnostic);main.innerHTML=`${intro('See what’s taking root.','Small samples stay small. Skills grow through evidence across days.','YOUR PROGRESS')}<div class="metrics"><div class="metric"><label>Vocabulary introduced</label><b>${m.seen}</b><span>${m.late} in Boxes 4–5</span></div><div class="metric"><label>Conjugation attempts</label><b>${all.filter(a=>a.verbEvidence).length}</b><span>Separate from word meanings</span></div><div class="metric"><label>Reading questions</label><b>${comp('reading').filter(a=>a.outcome==='correct').length}/${comp('reading').length}</b><span>Independent correct / attempted</span></div><div class="metric"><label>Listening questions</label><b>${comp('listening').filter(a=>a.outcome==='correct').length}/${comp('listening').length}</b><span>Text fallbacks excluded</span></div></div><section class="panel"><h2>Your skill evidence</h2><details><summary>How skill evidence works</summary><p class="tiny">Secure means a promising sample: at least 6 independent answers, 80% of the latest 10 correct, 2 dates and 3 variants. Grammar also needs actual typed production; verb skills need subject, tense and context breadth. Reading and listening have their own targets. This does not certify every form or fluent use. Hints, retries, reveals, diagnostic placement and self-assessment do not establish secure status.</p></details>${course.objectives.map(o=>{const st=evidenceState(all,o,Date.now());return `<div class="progress-row"><div><b>${label(o.chapterId)} · ${esc(o.title)}</b><small>${st.n} independent attempts · ${st.variants} variants · ${st.dates} dates${st.targetsTotal?` · ${st.targetsSeen||0}/${st.targetsTotal} form targets sampled`: ''}</small></div><span>${tag(st.state)}</span><span>${st.n?Math.round(st.accuracy*100)+'% correct':'No independent evidence'}<br>${button('Review skill','skill','text-button','data-id="'+o.id+'"')}</span></div>`;}).join('')}</section><div class="grid"><section class="panel"><h2>Catch-up readiness</h2><p>${scoped.filter(o=>evidenceState(all,o,Date.now()).state==='secure').length} of ${scoped.length} objectives through ${label(p().settings.position)} are secure. Lessons and graded evidence are tracked separately from personal-response completion.</p><p class="tiny">${p().lessons.length} lessons explored · ${all.filter(a=>a.outcome==='self-assessed').length} self-assessed responses. No automatic writing or pronunciation scores.</p>${button('Take / retake diagnostic','diagnostic')}</section><section class="panel"><h2>Showing up adds up.</h2><p class="tiny">Saved practice activity over the last 7 local dates.</p><div class="activity">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const n=all.filter(a=>dayKey(a.timestamp)===dayKey(+d)).length;return `<div><i style="height:${Math.min(45,n*3)+3}px" role="img" aria-label="${n} activities on ${d.toLocaleDateString()}"></i>${d.toLocaleDateString(undefined,{weekday:'short'})}</div>`;}).join('')}</div></section></div>${diag.length?`<section class="panel"><h2>Diagnostic: provisional findings</h2><p class="tiny">Latest sample: ${new Date(diag.at(-1).timestamp).toLocaleDateString()}. A 20-question sample through 2B does not test every variant or later chapters.</p>${report.filter(r=>r.tested).map(r=>`<p><b>${esc(r.title)}</b> · ${r.correct}/${r.tested}<br><span class="tiny">${esc(r.recommendation)}</span></p>`).join('')}</section>`:''}<section class="panel"><h2>Conjugation by verb, tense & person</h2><div class="table-wrap"><table><thead><tr><th>Form target</th><th>Independent correct / tried</th><th>Accent slips</th></tr></thead><tbody>${verbEvidenceRows(all)}</tbody></table></div></section>`;}
function verbEvidenceRows(attempts){const groups={};for(const a of attempts.filter(a=>a.verbEvidence&&!a.diagnostic&&!a.usedHint&&!a.revealed&&!a.retry&&!a.practiceOnly)){const v=a.verbEvidence,k=`${v.verb} · ${v.tense} · ${v.person}`;(groups[k]||=[]).push(a);}return Object.entries(groups).map(([k,a])=>`<tr><td>${esc(k)}</td><td>${a.filter(x=>x.outcome==='correct').length}/${a.length}</td><td>${a.filter(x=>x.outcome==='accent-or-orthography').length}</td></tr>`).join('')||'<tr><td colspan="3">No independent form evidence yet.</td></tr>';}
function renderSettings(){const u=p().settings;main.innerHTML=`${intro('Make it your practice.','Your pace, your class, your local learning space.','SETTINGS & BACKUP')}<section class="panel"><h2>Local profiles</h2><p>Each profile has its own settings, schedules and unfinished sessions. Profiles live in this browser; they are labels, not private accounts. Anyone using this browser can open them. A temporary guest session keeps its work in memory until you end it.</p><div class="toolbar"><div class="field"><label for="profile-select">Active profile</label><select id="profile-select">${state.profiles.map(x=>`<option value="${esc(x.id)}" ${x.id===p().id?'selected':''}>${esc(x.displayName)}</option>`).join('')}</select></div>${button('Add a local profile','add-profile')}</div></section><form id="settings-form" class="panel"><h2>Your learning preferences</h2><div class="field"><label for="settings-name">Display name</label><input id="settings-name" maxlength="60" value="${esc(p().displayName)}"></div><div class="toolbar"><div class="field"><label for="settings-position">Class position</label><select id="settings-position">${positionOptions(u.position)}</select></div><div class="field"><label for="settings-minutes">Daily target</label><select id="settings-minutes">${[10,15,20].map(n=>`<option value="${n}" ${n===u.minutes?'selected':''}>${n} minutes</option>`).join('')}</select></div></div><div class="field"><label for="settings-deck">Vocabulary scope</label><select id="settings-deck"><option value="class" ${u.deckMode==='class'?'selected':''}>Follow class position</option><option value="custom" ${u.deckMode!=='class'?'selected':''}>Custom word filters</option></select><p class="tiny">All three introductory teaching topics share the four introductory vocabulary lists. Custom filters stay as chosen in Words.</p></div><div class="toolbar"><div class="field"><label for="settings-new">New vocabulary per day (0–20)</label><input id="settings-new" type="number" min="0" max="20" value="${esc(u.newLimit)}" required></div><div class="field"><label for="settings-direction">Vocabulary direction</label><select id="settings-direction">${[['es-en','Spanish → English'],['en-es','English → Spanish'],['mixed','A mix of both']].map(([id,name])=>`<option value="${id}" ${id===u.direction?'selected':''}>${name}</option>`).join('')}</select></div></div><div class="toolbar"><div class="field"><label for="settings-limit">Word-review session size</label><select id="settings-limit">${[10,20,30,50].map(n=>`<option ${n===u.limit?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="settings-speed">Speech speed</label><select id="settings-speed">${[.5,.7,.85,1,1.15,1.25].map(n=>`<option value="${n}" ${n===u.speed?'selected':''}>${n}×</option>`).join('')}</select></div></div><label class="check"><input id="settings-vosotros" type="checkbox" ${u.vosotros?'checked':''}>Include vosotros/vosotras reference and drills</label><p class="tiny">Default plural address is ustedes. Regional varieties are valid; this control changes drill targets. Vos forms are explained culturally but are outside the assessed bank.</p><p class="tiny">Changes apply to future sessions. Unfinished sessions keep their captured settings and queue. Scheduled v2 reviews fall at local midnight after 1/2/4/7/14 calendar days; legacy timestamps stay unchanged until reviewed.</p><button type="submit" class="primary">Save preferences</button></form><section class="panel"><h2>Your progress travels with you.</h2><p>Export before changing devices or URLs. A learner backup adds one profile and keeps existing learners. An older full-browser backup replaces the collection after preview. Unmatched legacy records stay in an exportable recovery copy.</p><div class="stack">${button('↓ Download this learner’s backup','export','primary')}${button('↑ Import backup','import-dialog')}</div><details><summary>Advanced: all profiles and recovery copies</summary><p>These downloads can include other learners’ data. Keep them private.</p><div class="stack">${button('Download whole-browser backup','export-all')}${button('Export recovery copies','export-recovery')}</div></details><div></div><p class="tiny">${state.recovery.length} recovery records retained. ${volatile?'Storage is unavailable: export before closing this tab.':'Progress is in IndexedDB in this browser.'}</p><details><summary>Moving from the original Palabra app</summary><p>Export its Settings backup and import it here. Browser progress does not transfer automatically between web addresses.</p></details></section><section class="panel"><h2>Audio & accessibility</h2><p>${spanishVoice()?'A Spanish browser voice is available.':'No Spanish browser voice is currently available. Listening activities offer a clearly labeled reading fallback.'} Voice quality and availability depend on the browser/device. No microphone access or upload is required for speaking practice.</p><p>Use keyboard Tab and Enter, visible focus, the accent keys, and your device’s text zoom. The interface follows reduced-motion preferences.</p></section><section class="panel"><h2>A fresh start for this profile</h2><p>Other profiles remain available. An export is recommended before resetting.</p>${button('Reset this profile…','reset-profile','danger')}</section><section class="panel"><h2>About the learning material</h2><p>940 independent vocabulary cards; original lessons and exercises through 9B. Aligned to Realidades 1 topics, with no claim of publisher endorsement or exact edition transcription. Content received an author review against cited sources; a teacher’s independent review and exact class alignment remain valuable.</p><p class="tiny">No cloud sync, AI conversation, paid services, third-party tracking or account infrastructure. Fonts fall back to system fonts. Offline installation is a later improvement.</p></section>`;}
async function launch(queue,{diagnostic=false,practiceOnly=false,wordsOnly=false,assignment=null,prerequisiteCount=0}={}){
 await mutate((next,profile)=>{const at=Date.now();let session;if(diagnostic)session=startDiagnostic(profile,course,at);else if(queue){session={...plan(profile,course,data.cards,at,at>>>0,{id:crypto.randomUUID(),practiceOnly,wordsOnly:true}),queue:queue.map((id,i)=>({kind:'exercise',exerciseId:id,reason:i<prerequisiteCount?'Prerequisite quick check':'Chosen skill practice'}))};}else session=plan(profile,course,data.cards,at,at>>>0,{id:crypto.randomUUID(),practiceOnly,wordsOnly});if(assignment){session.settings.position=assignment.chapter;session.settings.minutes=assignment.minutes;session.settings.sections=vocabularyScope(assignment.chapter,data.sections);profile.onboarded=true;}if(!session.queue.length)throw Error('No scheduled items are available with these filters. Try Practice anytime, or select more chapters.');profile.sessions.push(session);profile.activeSession=session.id;},{renderAfter:false});location.hash='today';page='today';render();main.focus();}
function skillQueue(id){return practiceQueue(p(),course,{objectiveId:id});}
function selectedQueue(chap,kind){return practiceQueue(p(),course,{chapterId:chap,kind,limit:kind==='grammar'||kind==='all'?12:20});}
function spanishVoice(){return globalThis.speechSynthesis?.getVoices().find(v=>/^es[-_]/i.test(v.lang));}
function speak(text,{onError}={}){const voice=spanishVoice();if(!voice||!globalThis.SpeechSynthesisUtterance){toast('No Spanish voice is available. Use the labeled text fallback for this activity.');onError?.();return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.voice=voice;u.lang=voice.lang;u.rate=s()?.settings.speed||p().settings.speed;u.onstart=()=>{if(onError)draft({audioPlayed:true}).catch(()=>{});};u.onerror=()=>{toast('Audio could not play. You can use the text fallback.');onError?.();};speechSynthesis.speak(u);}
function sessionDraft(){const session=s(),entry=pendingDrafts.get(session.id);return {...session.drafts[session.cursor],...(entry?.index===session.cursor?{answer:entry.answer}:{})};}
function persistDraftJournal(){if(guestContext)return;try{if(pendingDrafts.size)localStorage.setItem(JOURNAL_KEY,JSON.stringify({revision:state.revision,entries:[...pendingDrafts.values()]}));else localStorage.removeItem(JOURNAL_KEY);}catch{status('Draft awaiting save · keep this tab open',true);}}
function stageAnswer(answer){const se=s();pendingDrafts.set(se.id,{profileId:p().id,sessionId:se.id,index:se.cursor,answer:answer.slice(0,4000)});persistDraftJournal();status('Saving draft…');clearTimeout(draftTimer);draftTimer=setTimeout(()=>mutate(()=>{},{renderAfter:false}).catch(()=>{}),300);}
window.addEventListener('pagehide',()=>{if(pendingDrafts.size)mutate(()=>{},{renderAfter:false}).catch(()=>{});});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&pendingDrafts.size)mutate(()=>{},{renderAfter:false}).catch(()=>{});});
async function draft(patch){const sid=s()?.id,index=s()?.cursor;if(!sid)return;await mutate((_,profile)=>{const session=profile.sessions.find(x=>x.id===sid);session.drafts[index]={...session.drafts[index],...patch};},{renderAfter:false});}
function accentKeys(){return `<div class="accent-keys" aria-label="Spanish character input">${['á','é','í','ó','ú','ü','ñ','¿','¡'].map(c=>button(c,'accent','','data-char="'+c+'" aria-label="Insert '+c+'"')).join('')}</div>`;}
function clockHtml(prompt){const match=prompt.match(/Clock (\d+):(\d+)/);if(!match)return '';const h=+match[1],m=+match[2],line=(angle,length,weight)=>`<line x1="70" y1="70" x2="${70+Math.sin(angle)*length}" y2="${70-Math.cos(angle)*length}" stroke="currentColor" stroke-width="${weight}" stroke-linecap="round"/>`;return `<svg viewBox="0 0 140 140" class="clock" role="img" aria-label="Clock showing ${h}:${String(m).padStart(2,'0')}"><circle cx="70" cy="70" r="65" fill="#f1edda" stroke="#aab79d"/>${[12,3,6,9].map((n,i)=>`<text x="${[70,124,70,16][i]}" y="${[24,76,128,76][i]}" text-anchor="middle" font-size="15">${n}</text>`).join('')}${line((h%12+m/60)*Math.PI/6,32,5)}${line(m*Math.PI/30,47,3)}<circle cx="70" cy="70" r="4" fill="currentColor"/></svg>`;}
function sceneHtml(scene){if(scene.kind==='rooms')return '<svg class="location-scene" viewBox="0 0 300 180" role="img" aria-label="Ana has a large rectangular room. Luis has a smaller rectangular room."><rect x="10" y="20" width="160" height="130" fill="#eaf0e3" stroke="#204f40"/><rect x="195" y="60" width="85" height="90" fill="#f7e8b5" stroke="#204f40"/><text x="90" y="90" text-anchor="middle">Ana</text><text x="237" y="110" text-anchor="middle">Luis</text></svg>';if(scene.kind==='shirt')return '<svg class="location-scene" viewBox="0 0 300 170" role="img" aria-label="A blue shirt is here beside the speaker. A green shirt is far away."><text x="20" y="30">Yo</text><path d="M60 60l25-20 20 10 20-10 25 20-12 18-13-8v65H85V70l-13 8z" fill="#7caac6" stroke="#204f40"/><path d="M210 50l15-12 12 6 12-6 15 12-7 11-8-5v38h-24V56l-8 5z" fill="#758d65"/><text x="100" y="160" text-anchor="middle">aquí</text><text x="238" y="120" text-anchor="middle">allá</text></svg>';const under=scene.relation==='under',objectY=under?115:30;return '<svg class="location-scene" viewBox="0 0 260 170" role="img" aria-label="'+esc(scene.object)+' is '+(under?'under':'above')+' the '+esc(scene.support)+'"><rect x="35" y="65" width="190" height="12" rx="3" fill="#758d65"/><path d="M50 77v75M210 77v75" stroke="#758d65" stroke-width="8"/><text x="130" y="61" text-anchor="middle" font-size="15">'+esc(scene.support)+'</text><rect x="85" y="'+objectY+'" width="90" height="25" rx="4" fill="#f2cd69"/><text x="130" y="'+(objectY+18)+'" text-anchor="middle" font-size="14">'+esc(scene.object)+'</text></svg>';}
function renderSession(){
 const session=s();if(session.feedback){renderFeedback();return;}if(session.completedAt||session.cursor>=session.queue.length){renderSummary();return;}
 const item=session.queue[session.cursor],e=item.kind==='exercise'?ex(item.exerciseId):null,d=sessionDraft();
 const lessonOrder=e?e.objectiveIds.map(obj).filter(Boolean):[];
 const needLesson=!session.diagnostic&&!d.introSkipped&&lessonOrder.find(o=>!p().lessons.includes(o.id));
 const top=`<div class="study-top"><h1>${session.diagnostic?'Find your starting point.':session.practiceOnly?'A little extra recall.':'Your daily practice.'}</h1><div class="stack">${button('Finish early','finish-early')}${button('Save & leave','leave-session')}</div></div><div class="bar" role="progressbar" aria-label="Session completion" aria-valuenow="${session.cursor}" aria-valuemin="0" aria-valuemax="${session.queue.length}"><span style="width:${session.cursor/session.queue.length*100}%"></span></div><div class="study-meta"><span>${session.cursor+1} of ${session.queue.length} · ${session.diagnostic?'Diagnostic':item.kind==='vocabulary'?'Vocabulary':esc(kindName(e.kind))}</span><span>${esc(item.reason)}</span></div>`;
 if(needLesson){main.innerHTML=`<div class="study">${top}<section class="exercise"><div class="eyebrow">BEFORE THIS ACTIVITY · OPTIONAL REVIEW</div><h2>${esc(needLesson.title)}</h2><p>Would a brief lesson help, or would you like to try a quick check first?</p>${e.prerequisites.length?`<details><summary>Earlier patterns you may want to review</summary>${e.prerequisites.map(id=>button(esc(obj(id).title),'lesson','text-button','data-id="'+id+'"')).join(' ')}</details>`:''}<div class="actions">${button('Read the brief lesson','read-session-lesson','','data-id="'+needLesson.id+'"')}${button('Try a quick check first →','skip-intro','primary')}</div><p class="tiny">Reading the lesson makes this supported practice. A quick check can add independent evidence; it does not mark the lesson complete.</p></section>${button('↶ Undo last answer','undo','text-button',session.undo.length?'':'disabled')}</div>`;return;}

 if(!e){const c=data.cards.find(c=>c.id===item.cardId),spanish=item.direction==='es-en',prompt=spanish?c.spanish:c.english,answer=spanish?c.english:c.spanish;main.innerHTML=`<div class="study">${top}<section class="exercise"><div class="stack">${tag(item.direction==='es-en'?'SPANISH → ENGLISH':'ENGLISH → SPANISH')}${tag(session.practiceOnly?'PRACTICE ONLY':`BOX ${p().progress[c.id]?.box||1}`)}</div><div class="flashword" ${spanish?'lang="es"':''}>${esc(prompt)}</div>${spanish||d.revealed?button('◖)) Hear Spanish','speak-current'):''}${d.revealed?`<div class="translation" ${!spanish?'lang="es"':''}>${esc(answer)}</div><p class="tiny">Compare your attempt, then grade your vocabulary recall honestly.</p><p>Your attempt: ${esc(d.answer||'Spoken aloud')}</p><div class="actions">${button('Still learning','vocab-miss')}${button('I remembered','vocab-correct','primary')}</div>`:`<label for="answer">Your attempt (optional for self-graded vocabulary)</label><input id="answer" class="answer" value="${esc(d.answer||'')}" autocomplete="off" spellcheck="false">${accentKeys()}${button('Show answer →','reveal-vocab','primary')}`}<p class="tiny">${session.practiceOnly?'Practice leaves boxes, review statistics and mastery evidence unchanged.':'Only the first scheduled assessment of this card on a local date changes its box. Same-day repeats are extra practice.'}</p></section>${button('↶ Undo last answer','undo','text-button',session.undo.length?'':'disabled')}</div>`;return;}
 const stimulus=course.stimuli.find(x=>x.id===e.stimulusId),isAudio=e.kind==='listening',isSelf=e.assessmentMode==='self';
 main.innerHTML=`<div class="study">${top}<section class="exercise"><div class="stack">${tag(label(e.chapterId))}${tag(isSelf?'SELF-ASSESSED':session.diagnostic?'PROVISIONAL SAMPLE':'ACTIVE PRACTICE')}</div>${stimulus?.kind==='reading'?`<h3>Read the message.</h3><p lang="es" class="passage">${esc(stimulus.SpanishText)}</p><details><summary>Glossary & introduced bridge words</summary><div class="glossary">${Object.entries(stimulus.glossary).map(([w,m])=>`<p><b lang="es">${esc(w)}</b>: ${esc(m)}</p>`).join('')}</div></details>`:''}${isAudio?`<div class="audio-box"><h3>Listen for meaning.</h3><p>${d.audioFallback?'Reading fallback · No listening evidence will be awarded.':spanishVoice()?'Spanish browser audio · transcript hidden until you choose it.':'No Spanish voice available. Choose the text fallback; it will count as supported reading.'}</p><div class="stack">${button('◖)) Play / replay','play-audio')}${button('Slower','slow-audio')}${button(d.audioFallback?'Text fallback active':'Use text fallback','audio-fallback')}${button('Reveal transcript','transcript')}</div>${d.revealed||d.audioFallback?`<p class="transcript" lang="es">${esc(stimulus.transcript)}</p>`:''}</div>`:''}${isSelf?`<h2>${esc(e.prompt)}</h2><p>${e.kind==='speaking'?'Say a response aloud. You may jot down notes. No recording or pronunciation scoring is performed.':'Write a few original sentences. This response is not automatically graded.'}</p>`:`${clockHtml(e.prompt)}${e.scene?sceneHtml(e.scene):''}<h2>${esc(e.prompt)}</h2>`}${e.kind==='speaking'?button('Hear a model response','speak-model'):''}<form id="answer-form"><label for="answer">${e.kind==='speaking'?'Your spoken-response notes':isSelf?'Your response':'Your answer'}</label>${e.options?`<select id="answer" required><option value="">Choose a sentence…</option>${e.options.map(option=>`<option value="${esc(option)}" ${d.answer===option?'selected':''}>${esc(option)}</option>`).join('')}</select>`:isSelf?`<textarea id="answer" lang="es" maxlength="4000">${esc(d.answer||'')}</textarea>`:`<input id="answer" class="answer" value="${esc(d.answer||'')}" autocomplete="off" spellcheck="false" maxlength="500">`}${e.options?'':accentKeys()}<div class="actions"><button type="submit" class="primary">${isSelf?'Compare with checklist →':'Check answer →'}</button>${!isSelf?button('I don’t know','dont-know'):''}</div></form>${!session.diagnostic&&e.objectiveIds.length?`<div class="stack" style="margin-top:15px">${button('See pattern / hint','hint','text-button')}${e.verbEvidence?button('Open verb reference','drill-reference','text-button','data-id="'+e.verbEvidence.verb+'"'):''}</div>`:''}${d.hintShown?`<div class="callout">${esc(e.verbEvidence?`Focus on ${e.verbEvidence.person} in ${e.verbEvidence.tense}. Recall the ending for ${e.verbEvidence.verb}; check whether its stem changes and whether it needs a written accent.`:'Read the whole sentence. Identify the person, number, gender or location being asked about, then recall the relevant pattern.')}<p class="tiny">A hint makes this supported practice, not independent evidence.</p></div>`:''}</section>${button('↶ Undo last answer','undo','text-button',session.undo.length?'':'disabled')}</div>`;
}
function renderFeedback(){const session=s(),f=session.feedback,e=ex(f.exerciseId),a=p().attempts.find(a=>a.id===f.attemptId);main.innerHTML=`<div class="study"><div class="study-top"><h1>${a.outcome==='correct'?'A little stronger.':a.outcome==='self-assessed'?'Make it your own.':'A useful place to pause.'}</h1>${button('Save & leave','leave-session')}</div><section class="exercise"><div class="eyebrow">${esc(kindName(e.kind))} · ${label(e.chapterId)}</div><h2>${esc(e.prompt)}</h2><p>Your ${e.kind==='speaking'?'notes':'answer'}: <span lang="es">${esc(a.answer||'I don’t know')}</span></p>${a.outcome==='self-assessed'?`<h3>Your comparison checklist</h3>${e.rubric.map((r,i)=>`<label class="check"><input type="checkbox" data-rubric="${i}" ${f.checklist?.[i]?'checked':''}>${esc(r)}</label>`).join('')}<h3>One possible response</h3><p class="passage" lang="es">${esc(e.model)}</p><p class="tiny">Completing a response records activity. This checklist is learner self-assessment, never a validated language or pronunciation score.</p>`:`<div class="feedback ${a.outcome==='correct'?'':'wrong'}" role="status" tabindex="-1"><h3>${({correct:'Correct. Bien hecho.','accent-or-orthography':'Almost: check the written accent.','incorrect':'Let’s look at the pattern.'})[a.outcome]}</h3><p>${esc(grade(a.answer,e).message)}</p><p class="tiny">${a.diagnostic?'Diagnostic sample · provisional placement only.':a.usedHint||a.revealed||a.practiceOnly?'Supported practice · not independent mastery evidence.':'First independent attempt saved. A retry helps learning without replacing this evidence.'}</p></div>${a.outcome!=='correct'?`<form id="retry-form"><label for="retry-answer">Try it again (practice)</label><input id="retry-answer" class="answer" autocomplete="off" spellcheck="false" value="${esc(f.retryAnswer||'')}" maxlength="500">${accentKeys()}<div class="actions"><button type="submit">Check retry</button>${e.verbEvidence?button('See verb reference','drill-reference','','data-id="'+e.verbEvidence.verb+'"'):''}</div><p role="status">${esc(f.retryMessage||'')}</p></form>`:''}`}<div class="actions">${button(session.cursor>=session.queue.length?'See your session summary →':'Next activity →','next','primary')}${button('↶ Undo this answer','undo')}</div></section></div>`;}
function renderSummary(){const session=s(),attempts=p().attempts.filter(a=>a.sessionId===session.id),correct=attempts.filter(a=>a.outcome==='correct').length,gaps=attempts.filter(a=>['incorrect','accent-or-orthography'].includes(a.outcome)).flatMap(a=>a.objectiveIds),names=[...new Set(gaps)].map(id=>obj(id)?.title).filter(Boolean);main.innerHTML=`<div class="study">${intro('A little adds up.',session.endedEarly?'Partial session · your completed work counts as activity.':`Practiced on ${new Date(session.completedAt||session.createdAt).toLocaleDateString()}.`,'YOUR SESSION',session.completedAt||session.createdAt)}<section class="panel"><h2>${session.diagnostic?'Here’s where to begin.':session.practiceOnly?'Extra recall, completed.':'Keep this momentum.'}</h2><p>${attempts.length} saved activities · ${correct} correct · ${attempts.filter(a=>a.outcome==='self-assessed').length} self-assessed responses.</p><p>${names.length?'Next, revisit '+names.map(esc).join(', ')+'.':'Keep revisiting these patterns on another day to build independent evidence.'}</p>${session.diagnostic?'<p>These findings are provisional. They guide review without changing your vocabulary boxes. See Progress for tested coverage and specific gaps.</p>':'<p>Correct first attempts add evidence. Hints, retries, transcript reveals, and personal-response checklists help you learn but cannot establish secure skills.</p>'}<div class="actions">${button('Back to Today →','finish','primary')}${button('↶ Undo last answer','undo','',session.undo.length?'':'disabled')}</div><a href="#progress">See skill evidence →</a></section></div>`;}
async function checkAnswer(answer){
 const session=s(),e=ex(session.queue[session.cursor].exerciseId),sid=session.id,index=session.cursor;
 const d=sessionDraft();const value=String(answer??$('#answer')?.value??'').trim();if(!value&&answer!=='')throw Error('Try an answer, or choose “I don’t know”.');
 await mutate((next,profile)=>{
  const updated=commit(profile,sid,{id:`${sid}:${index}`,index,answer:value,usedHint:d.usedHint,revealed:d.revealed,audioFallback:e.kind==='listening'&&(d.audioFallback||!d.audioPlayed||!spanishVoice())},course,data.cards,Date.now());
  const ses=updated.sessions.find(x=>x.id===sid);ses.feedback={exerciseId:e.id,attemptId:`${sid}:${index}`,checklist:{}};
  next.profiles[next.profiles.findIndex(x=>x.id===profile.id)]=updated;
 });main.querySelector('.feedback')?.focus();
}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup prepared. Keep it somewhere you can find it.');}
function importDialog(){showModal('Bring your progress along.',`<p>Choose a Palabra v1 or v2 JSON backup, or paste its JSON below. Nothing changes until you review and apply the preview.</p><label for="backup-file">Backup file (under 64 MB)</label><input id="backup-file" type="file" accept="application/json,.json"><div class="field" style="margin-top:20px"><label for="backup-json">Or paste backup JSON</label><textarea id="backup-json" maxlength="67108864" placeholder="{ … }"></textarea></div>${button('Preview pasted backup','preview-import','primary')}<p id="import-error" class="inline-error" role="alert"></p>`);}
function previewImport(raw){importPreview=previewBackup(raw,data.cards,data.sections,course);const r=importPreview.summary;showModal('Review your import.',`<div class="import-preview"><p>Version ${r.version} · ${r.profiles} profile(s)</p><div class="metrics"><div class="metric"><label>Matched</label><b>${r.matched}</b></div><div class="metric"><label>Unmatched</label><b>${r.unmatched}</b></div><div class="metric"><label>Invalid</label><b>${r.invalid}</b></div><div class="metric"><label>Migrated</label><b>${r.migrated}</b></div></div><p>${r.scope==='profile'?'Applying adds this learner as a profile and keeps everyone already saved here. A matching profile ID is assigned a new local ID.':'Applying replaces this browser’s current profile collection. A recovery snapshot is retained.'} Unmatched v1 cards will be preserved there. No grammar mastery is invented from vocabulary history.</p><div class="actions">${button('Apply this backup','apply-import','primary')}${button('Cancel','close-modal')}</div></div>`);}
document.addEventListener('click',async event=>{
 const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action,id=el.dataset.id;
 if(el.tagName==='BUTTON')event.preventDefault();
 try{if(pendingDrafts.size&&!['export','export-all','reload'].includes(action))await mutate(()=>{},{renderAfter:false});switch(action){
  case 'assignment-start':{const chosen=assignmentQueue(p(),course,assignmentScope,Date.now());await launch(chosen.ids,{assignment:assignmentScope,prerequisiteCount:chosen.prerequisiteCount});break;}
  case 'copy-practice-link':try{await navigator.clipboard.writeText($('#share-link').value);toast('Practice link copied.');}catch{$('#share-link').focus();$('#share-link').select();toast('Copy the selected practice link.');}break;
  case 'guest-start':if(!guestContext){const returnHash=location.hash,returnPage=page;guestContext={state:structuredClone(state),repo,volatile,stale};const temporary=emptyStore();temporary.profiles[0]=newProfile('guest','Guest');temporary.profiles[0].settings=structuredClone(p().settings);temporary.profiles[0].onboarded=true;temporary.activeProfile='guest';repo=memoryRepository();state=await repo.write(temporary,0);volatile=false;stale=false;page=returnPage==='assignment'?'assignment':'today';location.hash=returnPage==='assignment'?returnHash:'today';status('Temporary guest · download before ending',true);render();}break;
  case 'guest-end':showModal('End this temporary session?',`<p>Guest work exists only in this tab. Download a learner backup to keep it. Ending discards this temporary work and returns to the saved study space.</p><div class="actions">${button('Download guest backup','export','primary')}${button('Keep practicing','close-modal')}${button('End guest session','guest-confirm-end','danger')}</div>`);break;
  case 'guest-confirm-end':if(guestContext){const saved=guestContext;state=await saved.repo.read()||saved.state;repo=saved.repo;volatile=saved.volatile;stale=saved.stale;guestContext=null;pendingDrafts.clear();clearTimeout(draftTimer);modal.close();status(volatile?'Practice in memory only · Export before leaving':'Saved in this browser',volatile);page='today';location.hash='today';render();}break;
  case 'reload':location.reload();break;
  case 'more-nav':{const links=$('#mobile-nav');links.hidden=!links.hidden;el.setAttribute('aria-expanded',String(!links.hidden));break;}
  case 'skip-intro':await draft({introSkipped:true});render();break;
  case 'read-session-lesson':showModal(obj(id).title,lessonHtml(obj(id))+button('Ready to try →','complete-lesson','primary','data-id="'+id+'"'));break;
  case 'close-modal':modal.close();break;
  case 'start-daily':await launch();break;
  case 'start-words':await launch(null,{wordsOnly:true});break;
  case 'practice-words':await launch(null,{wordsOnly:true,practiceOnly:true});break;
  case 'diagnostic':await launch(null,{diagnostic:true});break;
  case 'resume-latest':case 'resume':await mutate((_,profile)=>{profile.activeSession=id||pendingSessions(profile)[0].id;});break;
  case 'leave-session':await mutate((_,profile)=>{profile.activeSession=null;});break;
  case 'finish-early':await mutate((_,profile)=>{const se=profile.sessions.find(x=>x.id===profile.activeSession);se.completedAt=Date.now();se.endedEarly=true;delete se.feedback;});break;
  case 'finish':await mutate((_,profile)=>{profile.activeSession=null;});break;
  case 'chapter':location.hash=`course/${id}`;break;
  case 'lesson':showModal(obj(id).title,lessonHtml(obj(id))+button(p().lessons.includes(id)?'Lesson explored · close':'Mark lesson explored','mark-lesson','primary','data-id="'+id+'"'));break;
  case 'mark-lesson':await mutate((_,profile)=>{if(!profile.lessons.includes(id))profile.lessons.push(id);});modal.close();break;
  case 'complete-lesson':await mutate((_,profile)=>{if(!profile.lessons.includes(id))profile.lessons.push(id);const session=profile.sessions.find(x=>x.id===profile.activeSession);session.drafts[session.cursor]={...session.drafts[session.cursor],usedHint:true};});if(modal.open)modal.close();break;
  case 'skill':await launch(skillQueue(id));break;
  case 'verb-practice':{const items=course.exercises.filter(e=>e.verbEvidence?.verb===id&&(!e.vosotros||p().settings.vosotros));if(!items.length){toast('This reference has no separate form drill yet. Use its chapter’s sentence practice.');break;}showModal('Choose your verb practice',`<form id="verb-drill-form" data-verb="${esc(id)}"><p>Practice ${esc(id)} in original sentences. Only forms with reviewed exercises are offered.</p><div class="field"><label for="drill-tense">Tense or instruction</label><select id="drill-tense"><option value="all">All available tenses</option>${[...new Set(items.map(e=>e.verbEvidence.tense))].map(v=>`<option value="${esc(v)}">${esc(v==='affirmative-tú'?'Affirmative tú command':v)}</option>`).join('')}</select></div><div class="field"><label for="drill-person">Subject</label><select id="drill-person"><option value="all">All available subjects</option>${[...new Set(items.map(e=>e.verbEvidence.person))].map(v=>`<option>${esc(v)}</option>`).join('')}</select></div><button type="submit" class="primary">Start verb practice →</button></form>`);break;}
  case 'chapter-practice':await launch(selectedQueue(el.dataset.chapter,el.dataset.kind));break;
  case 'start-selected':await launch(selectedQueue(practiceChapter,practiceKind));break;
  case 'word-prev':wordPage--;renderWords();break;
  case 'word-next':wordPage++;renderWords();break;
  case 'box-filter':wordBox=id;wordPage=0;renderWords();break;
  case 'word-filters':showModal('Choose your vocabulary.',`<p>The four introductory data lists are filters, not four official textbook topics.</p><div class="stack">${button('Through 2B','filter-catchup')}${button('Whole book','filter-all')}</div><form id="filters-form">${data.sections.map(section=>`<label class="check"><input type="checkbox" name="sections" value="${esc(section.id)}" ${p().settings.sections.includes(section.id)?'checked':''}>${esc(section.title)}</label>`).join('')}<button type="submit" class="primary">Use these filters</button></form>`);break;
  case 'filter-catchup':case 'filter-all':modal.querySelectorAll('[name=sections]').forEach(x=>x.checked=action==='filter-all'||data.sections.find(s=>s.id===x.value).catchup);break;
  case 'speak-word':speak(data.cards.find(c=>c.id===id).spanish);break;
  case 'speak-verb':speak(id);break;
  case 'speak-current':speak(data.cards.find(c=>c.id===s().queue[s().cursor].cardId).spanish);break;
  case 'speak-model':speak(ex(s().queue[s().cursor].exerciseId).model);break;
  case 'play-audio':{const e=ex(s().queue[s().cursor].exerciseId),st=course.stimuli.find(x=>x.id===e.stimulusId);speak(st.SpanishText,{onError:()=>draft({audioFallback:true}).then(render)});break;}
  case 'slow-audio':await mutate((_,profile)=>{profile.sessions.find(x=>x.id===profile.activeSession).settings.speed=.6;});toast('This session’s speech speed is now 0.6×.');break;
  case 'audio-fallback':await draft({audioFallback:true});render();break;
  case 'transcript':await draft({revealed:true});render();break;
  case 'hint':await draft({usedHint:true,hintShown:true,answer:$('#answer')?.value||''});render();break;
  case 'drill-reference':{const v=course.verbs.find(v=>v.id===id);if(s()&&!s().feedback)await draft({revealed:true,answer:$('#answer')?.value||''});showModal(`${v.infinitive} · ${v.meaning}`,`<p>${esc(v.notes)}</p>${Object.entries(v.forms).map(([tense,forms])=>`<h3>${esc(tense)}</h3><p lang="es">${forms.map((f,i)=>`${esc(tense==='affirmative-tú'?'tú':PERSONS[i])}: <b>${esc(f)}</b>`).join('<br>')}</p>`).join('')}<p class="tiny">${refs(v.sourceRefs)}</p><p>Looking up this form is exposure, not successful independent recall.</p>`);break;}
  case 'accent':{const input=$('#answer')||$('#retry-answer');if(input){const at=input.selectionStart,end=input.selectionEnd;input.value=input.value.slice(0,at)+el.dataset.char+input.value.slice(end);input.focus();input.setSelectionRange(at+1,at+1);input.dispatchEvent(new Event('input',{bubbles:true}));}break;}
  case 'reveal-vocab':await draft({revealed:true,answer:$('#answer')?.value||''});render();break;
  case 'vocab-miss':case 'vocab-correct':{const session=s(),sid=session.id,index=session.cursor;await mutate((next,profile)=>{const updated=commit(profile,sid,{id:`${sid}:${index}`,index,answer:session.drafts[index]?.answer||'',correct:action==='vocab-correct'},course,data.cards,Date.now());next.profiles[next.profiles.findIndex(x=>x.id===profile.id)]=updated;});break;}
  case 'dont-know':await checkAnswer('');break;
  case 'next':await mutate((_,profile)=>{delete profile.sessions.find(x=>x.id===profile.activeSession).feedback;});($('#answer')||main).focus();break;
  case 'undo':{const sid=s().id;await mutate((next,profile)=>{const updated=undo(profile,sid);delete updated.sessions.find(x=>x.id===sid).feedback;next.profiles[next.profiles.findIndex(x=>x.id===profile.id)]=updated;});break;}
  case 'export-all':download(`palabra-browser-${dayKey(Date.now())}.json`,exportBackup(state));break;
  case 'export':download(`palabra-learner-${dayKey(Date.now())}.json`,exportProfileBackup(recoverDrafts(state,JSON.stringify({revision:state.revision,entries:[...pendingDrafts.values()]}))));break;
  case 'export-recovery':download(`palabra-recovery-${dayKey(Date.now())}.json`,JSON.stringify({recovery:state.recovery},null,2));break;
  case 'import-dialog':importDialog();break;
  case 'preview-import':previewImport($('#backup-json').value);break;
  case 'apply-import':{const backup=importPreview;await mutate(next=>{if(backup.summary.scope==='profile'){const combined=addImportedProfile(next,backup.state,()=>crypto.randomUUID());Object.assign(next,combined);return;}const previous={...structuredClone(next),recovery:[]},priorRevision=next.revision;Object.assign(next,structuredClone(backup.state));next.revision=priorRevision;next.recovery.push({reason:'State before backup replacement. Retained for recovery.',backup:JSON.parse(exportBackup(previous))});/* Original v1 records already live in recovery; v2 is represented by its validated state. */});modal.close();importPreview=null;location.hash='today';break;}
  case 'add-profile':showModal('A new local study space.',`<form id="profile-form"><div class="field"><label for="new-profile-name">Display name</label><input id="new-profile-name" maxlength="60" required></div><p class="tiny">The current profile and unfinished session stay saved.</p><button type="submit" class="primary">Create local profile</button></form>`);break;
  case 'reset-profile':showModal('Reset this profile?',`<p>This resets ${esc(p().displayName)}’s learning history and unfinished sessions. Other profiles remain. A recovery snapshot is retained in Settings.</p><div class="actions">${button('Keep learning','close-modal','primary')}${button('Reset this profile','confirm-reset','danger')}</div>`);break;
  case 'confirm-reset':await mutate((next,profile)=>{next.recovery.push({reason:'Profile before explicit reset',profile:structuredClone(profile)});const fresh=newProfile(profile.id,profile.displayName);fresh.settings=profile.settings;fresh.onboarded=true;next.profiles[next.profiles.findIndex(x=>x.id===profile.id)]=fresh;});modal.close();break;
 }}catch(error){toast(error.message);if($('#import-error'))$('#import-error').textContent=error.message;}
});
document.addEventListener('submit',async event=>{
 event.preventDefault();const form=event.target;
 try{if(pendingDrafts.size)await mutate(()=>{},{renderAfter:false});
  if(form.id==='onboarding-form'){const diagnostic=event.submitter?.value==='diagnostic';await mutate((_,profile)=>{profile.displayName=$('#display-name').value.trim()||'Learner';profile.settings.position=$('#class-position').value;profile.settings.deckMode='class';profile.settings.sections=vocabularyScope(profile.settings.position,data.sections);profile.settings.minutes=Number($('#time-budget').value);profile.onboarded=true;},{renderAfter:false});if(diagnostic)await launch(null,{diagnostic:true});else render();}
  if(form.id==='teacher-link-form'){const scope={chapter:$('#teacher-chapter').value,skill:$('#teacher-skill').value,kind:'all',minutes:Number($('#teacher-minutes').value)},url=assignmentLink(location.href,scope);showModal('Your class practice link',`<p>Students see a preview before starting. No learning records are included.</p><label for="share-link">Practice URL</label><input id="share-link" readonly value="${esc(url)}" style="width:100%"><div class="actions">${button('Copy link','copy-practice-link','primary')}<a class="button" href="${esc(url)}" data-action="close-modal">Open preview</a></div>`);}
  if(form.id==='verb-drill-form'){const ids=practiceQueue(p(),course,{verb:form.dataset.verb,tense:$('#drill-tense').value,person:$('#drill-person').value});if(!ids.length)throw Error('There are no reviewed exercises for that tense and subject combination. Choose another subject.');modal.close();await launch(ids);}
  if(form.id==='answer-form')await checkAnswer();
  if(form.id==='retry-form'){const a=$('#retry-answer').value,e=ex(s().feedback.exerciseId),g=grade(a,e);await mutate((_,profile)=>{const se=profile.sessions.find(x=>x.id===profile.activeSession);se.feedback.retryAnswer=a;se.feedback.retryMessage=g.message;const original=profile.attempts.find(x=>x.id===se.feedback.attemptId);profile.attempts.push({...original,id:crypto.randomUUID(),answer:a,outcome:g.outcome,timestamp:Date.now(),retry:true,practiceOnly:true});});}
  if(form.id==='settings-form'){const values={deckMode:$('#settings-deck').value,displayName:$('#settings-name').value.trim()||'Learner',position:$('#settings-position').value,minutes:Number($('#settings-minutes').value),newLimit:Number($('#settings-new').value),direction:$('#settings-direction').value,limit:Number($('#settings-limit').value),speed:Number($('#settings-speed').value),vosotros:$('#settings-vosotros').checked};await mutate((_,profile)=>{profile.displayName=values.displayName;Object.assign(profile.settings,{...values});delete profile.settings.displayName;if(profile.settings.deckMode==='class')profile.settings.sections=vocabularyScope(profile.settings.position,data.sections);});toast('Preferences saved for future sessions.');}
  if(form.id==='profile-form'){const name=$('#new-profile-name').value.trim();if(!name)return;await mutate(next=>{const profile=newProfile(crypto.randomUUID(),name);next.profiles.push(profile);next.activeProfile=profile.id;});modal.close();location.hash='today';}
  if(form.id==='filters-form'){const ids=Array.from(form.querySelectorAll('input:checked')).map(x=>x.value);if(!ids.length)throw Error('Select at least one vocabulary section.');await mutate((_,profile)=>{profile.settings.sections=ids;profile.settings.deckMode='custom';});modal.close();wordPage=0;}
 }catch(error){toast(error.message);}
});
document.addEventListener('input',event=>{
 const el=event.target;
 if(el.id==='word-search'){const at=el.selectionStart;query=el.value;wordPage=0;renderWords();$('#word-search').focus();$('#word-search').setSelectionRange(at,at);}
 if(el.id==='verb-search'){const at=el.selectionStart;verbQuery=el.value;renderVerbs();$('#verb-search').focus();$('#verb-search').setSelectionRange(at,at);}
 if(el.id==='answer'&&s()&&!s().feedback)stageAnswer(el.value);
});
document.addEventListener('change',async event=>{const el=event.target;try{
 if(el.id==='answer'&&s()&&!s().feedback)stageAnswer(el.value);
 if(el.id==='word-box'){wordBox=el.value;wordPage=0;renderWords();}
 if(el.id==='word-verbs')await mutate((_,profile)=>{profile.settings.verbsOnly=el.checked;});
 if(el.id==='teacher-chapter'){practiceChapter=el.value;renderPractice();}
 if(el.id==='practice-chapter'){practiceChapter=el.value;renderPractice();}
 if(el.id==='practice-kind'){practiceKind=el.value;renderPractice();}
 if(el.id==='profile-select')await mutate(next=>{next.activeProfile=el.value;});
 if(el.dataset.rubric)await mutate((_,profile)=>{profile.sessions.find(x=>x.id===profile.activeSession).feedback.checklist[el.dataset.rubric]=el.checked;},{renderAfter:false});
 if(el.id==='backup-file'){const file=el.files[0];if(!file)return;if(file.size>MAX_BACKUP_BYTES)throw Error('Choose a backup smaller than 64 MB. Nothing was changed.');previewImport(await file.text());}
 }catch(error){toast(error.message);if($('#import-error'))$('#import-error').textContent=error.message;}});
document.addEventListener('keydown',event=>{
 if(modal.open||!s()||s().feedback)return;
 if(event.target.id==='answer'&&event.key==='Enter'&&s().queue[s().cursor]?.kind==='vocabulary'&&!sessionDraft().revealed){event.preventDefault();main.querySelector('[data-action=reveal-vocab]')?.click();return;}
 if(['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName))return;
 if(s().queue[s().cursor]?.kind==='vocabulary'){
  if(!sessionDraft().revealed&&['Enter',' '].includes(event.key)&&event.target===document.body){event.preventDefault();main.querySelector('[data-action=reveal-vocab]')?.click();}
  if(sessionDraft().revealed&&['1','2'].includes(event.key)){event.preventDefault();main.querySelector(`[data-action=${event.key==='1'?'vocab-miss':'vocab-correct'}]`)?.click();}
 }
});
window.addEventListener('beforeunload',event=>{if(guestContext&&(p().attempts.length||pendingDrafts.size)){event.preventDefault();event.returnValue='';}});
window.addEventListener('hashchange',async()=>{if(pendingDrafts.size)await mutate(()=>{},{renderAfter:false}).catch(()=>{});navigate();});
try{
 const response=await fetch(new URL('../content/vocabulary.json',import.meta.url));if(!response.ok)throw Error('Vocabulary could not load. Refresh the page to try again.');data=await response.json();
 try{repo=await openRepository();state=await repo.read();if(state)previewBackup(exportBackup(state),data.cards,data.sections,course);}
 catch(error){const unreadable=state;volatile=true;repo=memoryRepository();state=emptyStore();state.recovery.push({reason:'Local storage could not be opened. Existing browser data was not overwritten.',message:error.message,raw:unreadable||null});status('Practice in memory only · Export before leaving',true);toast(error.message);}
 if(!state){state=emptyStore();let legacy=null;try{legacy=localStorage.getItem('palabra-progress-v1');}catch{}
  if(legacy){try{const old=JSON.parse(legacy);const migrated=previewBackup(JSON.stringify({...old,format:'palabra-backup'}),data.cards,data.sections,course);state=migrated.state;toast(`Migrated ${migrated.summary.matched} vocabulary schedules. The original v1 data is preserved.`);}catch(error){state.recovery.push({reason:'Legacy data could not be migrated; unchanged original retained.',raw:legacy});toast(error.message);}}
  try{state=await repo.write(state,0);}catch(error){volatile=true;repo=memoryRepository();state=await repo.write(state,0);toast('Device storage could not save. Practice in memory and export before leaving.');}
 }
 try{state=recoverDrafts(state,localStorage.getItem(JOURNAL_KEY));}catch{}
 status(volatile?'Practice in memory only · Export before leaving':'Saved in this browser');navigate();
}catch(error){main.innerHTML=`<section class="empty"><h1>Your study space couldn’t open.</h1><p>${esc(error.message)}</p><button onclick="location.reload()">Try again</button></section>`;}
